"""Group B (budgets and hard limits). Stored vectors are small; oversize vectors are generated by a deterministic function,
judged by lodlib, and recorded as sizes plus SHA-256 in generated/GENERATED.tsv (they are not stored)."""
import json, os, sys
from gen_infra import *
from g_wam import X, W_NODES, W_EDGES, W_POS, OUTER

GEN_FILES = {}       # id -> {role: callable returning bytes}
FULL = os.environ.get("LOD_FULL", "1") == "1"


def junk(n, ch=b"x"):
    return ch * n


def run_b():
    w = X["w"]
    sc, sb, lay, lb = w["sc"], w["sb"], w["lay"], w["lb"]
    A = "states/W01.state.json"
    V_derive("B02s", "B", sc, lay, A, {"maxNodes": 6})
    V_derive("B02t", "B", sc, lay, A, {"maxNodes": 7})                      # exactly at the node budget: accepted
    V_derive("B03s", "B", sc, lay, A, {"maxEdges": 9})
    V_derive("B03t", "B", sc, lay, A, {"maxEdges": 10})
    # B04s: stage order, 20,001 groups with no members at all: GROUP_LIMIT precedes EMPTY_GROUP
    o = json.loads(rd(A).decode())
    txt = cj({**o, "collapsed": []}).replace('"collapsed":[]', '"collapsed":[' + ",".join(['{"members":[]}'] * 20001) + "]")
    V_verify("B04s", "B", put("states/B04s.state.json", txt.encode()))
    txt = cj({**o, "collapsed": []}).replace('"collapsed":[]', '"collapsed":[' + ",".join(['{"members":[]}'] * 20000) + "]")
    V_verify("B04t", "B", put("states/B04t.state.json", txt.encode()))
    # B06 label limit (UTF-16 code units)
    for nm, lab in (("B06a", "a" * 257), ("B06b", "a" * 256), ("B06c", "\U0001F600" * 128), ("B06d", "\U0001F600" * 129), ("B06e", "\U0001F600" * 128 + "a"),
                    ("B06f", "")):
        oo = json.loads(rd(A).decode())
        oo["collapsed"][0]["label"] = lab
        V_verify(nm, "B", put("states/%s.state.json" % nm, cjb(oo)))
    # B07 work limit (refused after binding, before any LOD pass)
    V_derive("B07a", "B", sc, lay, A, {"maxWork": 1})
    V_derive("B07b", "B", sc, lay, "states/W02.state.json", {"maxWork": 1000})
    # B08 exact boundary: W01 3127, W02 3492, W03 3507
    for (ida, idb), st, W in ((("B08a", "B08b"), "W01", 3127), (("B08c", "B08d"), "W02", 3492), (("B08e", "B08f"), "W03", 3507)):
        r = V_derive(ida, "B", sc, lay, "states/%s.state.json" % st, {"maxWork": W})
        assert r[0] == "ok"
        r = V_derive(idb, "B", sc, lay, "states/%s.state.json" % st, {"maxWork": W - 1})
        assert r == ("err", "RESOURCE_LIMIT/WORK_LIMIT")
    # B09 above a hard limit is an error, never clamped
    V_derive("B09a", "B", sc, lay, A, {"maxNodes": 100001})
    V_derive("B09b", "B", sc, lay, A, {"maxEdges": 500001})
    V_derive("B09c", "B", sc, lay, A, {"maxWork": 1000000001})
    r = V_derive("B09d", "B", sc, lay, A, {"maxNodes": 100000, "maxEdges": 500000, "maxWork": 1000000000})
    assert r[0] == "ok"
    # B10 malformed budgets (the call file is canonical IGS-CJ/1, so negative and fractional values cannot be spelled)
    V_derive("B10a", "B", sc, lay, A, {"maxFoo": 5})
    V_derive("B10b", "B", sc, lay, A, {"maxWork": 0})
    V_derive("B10c", "B", sc, lay, A, {"maxNodes": "5"})
    V_derive("B10d", "B", sc, lay, A, {"maxEdges": True})
    V_derive("B10e", "B", sc, lay, A, {"maxNodes": 0})
    V_derive("B10f", "B", sc, lay, A, {"maxWork": -1})                  # rev 3: negative values can be written (IGL-CJ/1 call files)
    V_derive("B10g", "B", sc, lay, A, {"maxEdges": -5, "maxNodes": 3})
    # B11 a budget never changes the output bytes
    ra = V_derive("B11a", "B", sc, lay, "states/W02.state.json", {"maxNodes": 7, "maxEdges": 10, "maxWork": 3492})
    rb = V_derive("B11b", "B", sc, lay, "states/W02.state.json", {"maxNodes": 100000, "maxEdges": 500000, "maxWork": 1000000000})
    assert ra == ("ok", rd("expected/W02.view.json")) and rb == ra
    # B14 long identifiers: 1,000 and 16,384 UTF-16 units (ASCII and astral)
    for nm, idtxt in (("B14a", "s:" + "a" * 998), ("B14b", "s:" + "b" * 16382), ("B14c", "s:" + "\U0001F600" * 8191)):
        n0, n1 = (nm + "x", idtxt), ("t", "s:z")
        nodes = [idtxt, "s:z", "s:" + "c" * 3]
        s = mkscene(nm, nodes, [("r", idtxt, "s:z"), ("r", "s:z", "s:ccc")])
        l = mklayout(nm, s[1])
        st = mkstate(nm, s[1], l[1], [[idtxt, "s:z"]])
        r = V_derive(nm, "B", s[0], l[0], st[0])
        assert r[0] == "ok", r
        assert len(idtxt.encode("utf-16-le")) // 2 in (1000, 16384)
    # B15 suggestGroups budgets and resolveAggregateEdge budgets
    pf = [{"rule": "pendant-fold/1", "min_leaves": 2}]
    V_suggest("B15a", "B", sc, pf, {"maxNodes": 6})
    V_suggest("B15b", "B", sc, pf, {"maxEdges": 9})
    r = V_suggest("B15c", "B", sc, pf, {"maxWork": 197})
    assert r[0] == "ok"
    r = V_suggest("B15d", "B", sc, pf, {"maxWork": 196})
    assert r == ("err", "RESOURCE_LIMIT/WORK_LIMIT")
    aid = json.loads(rd("expected/W02.view.json"))["aggregates"][0]["id"]
    V_edge("B15e", "B", sc, lay, "states/W02.state.json", R("i:1"), {"agg": aid}, budget={"maxEdges": 9})
    V_edge("B15f", "B", sc, lay, "states/W02.state.json", R("i:1"), {"agg": aid}, budget={"maxWork": 1})
    run_big()


# ---------------------------------------------------------------------------------------------- oversize (generated)
def addgen(id, group, files, inp, expect_kind, run, note=""):
    """files: {role: bytes-producing callable}; run(bytes-dict) -> ('ok', bytes)|('err', tag)."""
    data = {k: f() for k, f in files.items()}
    paths = {}
    for k, b in data.items():
        paths[k] = "generated/%s.%s.json" % (id, k)
        GENERATED.append((id, k, paths[k], len(b), sha(b)))
    res = run(data)
    if res[0] == "err":
        addrow(id, group, paths.get("scene", "-"), paths.get("layout", "-"), paths.get("state", "-"), inp, "-", res[1])
    else:
        ep = "generated/%s.expected.json" % id
        GENERATED.append((id, "expected", ep, len(res[1]), sha(res[1])))
        addrow(id, group, paths.get("scene", "-"), paths.get("layout", "-"), paths.get("state", "-"), inp, ep, "")
    GEN_FILES[id] = files
    del data
    return res


def mk_nodes(n, prefix="s:n"):
    return ["%s%06d" % (prefix, i) for i in range(n)]


def big_scene(nodes, edges_fn, directed=True):
    nn = [("t", x) for x in nodes]
    return build_scene(nn, edges_fn, directed)


def run_big():
    w = X["w"]
    stA = rd("states/W01.state.json")
    wl, ws = rd(w["lay"]), rd(w["sc"])
    A_state = stA

    # B01: INPUT_BYTES (total of scene + layout + state above 256 MiB; sizes only, nothing is parsed)
    lim = MAX_INPUT_BYTES
    jb = lambda extra: (lambda: b"x" * (lim + extra - len(wl) - len(A_state)))
    addgen("B01", "B", {"scene": jb(1), "layout": lambda: wl, "state": lambda: A_state}, "-", "view",
           lambda d: ("err", derive_err(d)))
    addgen("B01t", "B", {"scene": jb(0), "layout": lambda: wl, "state": lambda: A_state}, "-", "view",
           lambda d: ("err", derive_err(d)))
    # B16: STATE_BYTES
    SB = MAX_STATE_BYTES
    addgen("B16", "B", {"scene": lambda: ws, "layout": lambda: wl, "state": lambda: b"y" * (SB + 1)}, "-", "view", lambda d: ("err", derive_err(d)))
    addgen("B16t", "B", {"scene": lambda: ws, "layout": lambda: wl, "state": lambda: b"y" * SB}, "-", "view", lambda d: ("err", derive_err(d)))
    # B16v: the standalone verifyLODState also applies MAX_STATE_BYTES (rev 3)
    addgen("B16v", "B", {"state": lambda: b"y" * (SB + 1)}, "-", "state", lambda d: _verify(d["state"]))
    addgen("B16vt", "B", {"state": lambda: b"y" * SB}, "-", "state", lambda d: _verify(d["state"]))
    if not FULL:
        return

    # B02: NODE_LIMIT at the hard limit (budget raised to 100,000) and at the default budget (20,000)
    def nodes_case(id, n, budget):
        def scene():
            return build_scene([("t", x) for x in mk_nodes(n)], [], True)

        def layout():
            return build_layout(sha(scene()), [({"id": x, "type": "t"}, 0, 0) for x in mk_nodes(n)])
        cache = {}

        def getall():
            if not cache:
                s = scene()
                l = build_layout(sha(s), [({"id": x, "type": "t"}, i % 100, i // 100) for i, x in enumerate(mk_nodes(n))])
                cache.update(scene=s, layout=l, state=mkstate_bytes(s, l, []))
            return cache
        inp = call(id, "deriveView", {}, {"budget": budget}) if budget else "-"
        return addgen(id, "B", {"scene": lambda: getall()["scene"], "layout": lambda: getall()["layout"], "state": lambda: getall()["state"]}, inp, "view",
                      lambda d: _run(d, budget))
    nodes_case("B02", 100001, {"maxNodes": 100000})
    nodes_case("B02d", 20000, None)      # inclusive limit: exactly the default node budget passes
    nodes_case("B02e", 20001, None)

    def edges_case(id, n, m, budget, directed=True):
        cache = {}

        def getall():
            if not cache:
                names = mk_nodes(n)
                edges = []
                i = 0
                for a in range(n):
                    for b in range(n):
                        if a != b and len(edges) < m:
                            edges.append(("r", "t", names[a], "t", names[b]))
                s = build_scene([("t", x) for x in names], edges, directed)
                l = build_layout(sha(s), [({"id": x, "type": "t"}, i, 0) for i, x in enumerate(names)])
                cache.update(scene=s, layout=l, state=mkstate_bytes(s, l, []))
            return cache
        inp = call(id, "deriveView", {}, {"budget": budget}) if budget else "-"
        return addgen(id, "B", {"scene": lambda: getall()["scene"], "layout": lambda: getall()["layout"], "state": lambda: getall()["state"]}, inp, "view",
                      lambda d: _run(d, budget))
    edges_case("B03d", 400, 100000, None)   # inclusive: exactly the default edge budget passes
    edges_case("B03e", 400, 100001, None)
    edges_case("B03", 710, 500001, {"maxEdges": 500000})

    # B04: GROUP_LIMIT, valid-looking pairs (verifyLODState, state only); M14b: unsorted and over the limit: GROUP_LIMIT before NON_CANONICAL
    def pair_state(ng, reverse=False, entries=None):
        def f():
            base = json.loads(A_state.decode())
            names = mk_nodes(2 * ng)
            groups = [[R(names[2 * i]), R(names[2 * i + 1])] for i in range(ng)]
            if reverse:
                groups.reverse()
            base["collapsed"] = [{"members": g} for g in groups]
            if reverse:                                   # canonical re-sort would undo it: serialize by hand
                return cjb({**base, "collapsed": []}).decode().replace('"collapsed":[]', '"collapsed":' + cj(base["collapsed"])).encode()
            return cjb(base)
        return f
    for id, ng, rev in (("B04", 20001, False), ("B04o", 20000, False), ("M14b", 20001, True)):
        addgen(id, "B" if id != "M14b" else "M", {"state": pair_state(ng, rev)}, "-", "state", lambda d: _verify(d["state"]))

    # B05: MEMBER_LIMIT: depth-16 nested chain on 31,258 nodes with exactly 500,001 (error) / 500,000 (accepted) entries
    def chain_state(total):
        def f():
            n = 31258
            names = mk_nodes(n)
            sizes = [n - j for j in range(15)]
            sizes.append(total - sum(sizes))
            assert sizes[-1] < sizes[-2] and sizes[-1] >= 2
            base = json.loads(A_state.decode())
            base["collapsed"] = [{"members": [R(x) for x in names[:sz]]} for sz in sizes]
            return cjb(canonical_state_obj(base))
        return f
    addgen("B05", "B", {"state": chain_state(500001)}, "-", "state", lambda d: _verify(d["state"]))
    addgen("B05o", "B", {"state": chain_state(500000)}, "-", "state", lambda d: _verify(d["state"]))

    # B17: suggestGroups over GROUP_LIMIT (60,003 nodes: 20,001 hosts with two leaves each) and exactly at the limit
    def hosts_case(id, nh, budget):
        cache = {}

        def getall():
            if not cache:
                nodes, edges = [], []
                for h in range(nh):
                    hn = "s:h%05d" % h
                    nodes += [hn, "s:h%05dl0" % h, "s:h%05dl1" % h]
                    edges += [("r", "t", hn, "t", "s:h%05dl0" % h), ("r", "t", hn, "t", "s:h%05dl1" % h)]
                cache["scene"] = build_scene([("t", x) for x in nodes], edges, True)
            return cache
        pf = [{"rule": "pendant-fold/1", "min_leaves": 2}]
        inp = call(id, "suggestGroups", {"rules": pf}, {"budget": budget})
        return addgen(id, "B", {"scene": lambda: getall()["scene"]}, inp, "catalog",
                      lambda d: _suggest(d["scene"], pf, budget))
    hosts_case("B17", 20001, {"maxNodes": 100000})
    hosts_case("B17o", 20000, {"maxNodes": 100000})


def derive_err(d):
    try:
        derive_view(d["scene"], d["layout"], d["state"])
    except LODErr as e:
        return e.tag()
    raise AssertionError("expected an error")


def _run(d, budget):
    try:
        return ("ok", derive_view(d["scene"], d["layout"], d["state"], budget)[1])
    except LODErr as e:
        return ("err", e.tag())


def _verify(b):
    try:
        return ("ok", verify_state(b)[1])
    except LODErr as e:
        return ("err", e.tag())


def _suggest(b, rules, budget):
    try:
        return ("ok", cjb(suggest_groups(b, rules, budget), True))
    except LODErr as e:
        return ("err", e.tag())


def write_generated():
    lines = "id\trole\tpath\tbytes\tsha256\n" + "".join("%s\t%s\t%s\t%d\t%s\n" % g for g in GENERATED)
    put("generated/GENERATED.tsv", lines)


def materialize(dest):
    """Writes every oversize file named in GENERATED.tsv (they are deterministic) under dest, keeping the names 'generated/<id>.<role>.json'."""
    for id, files in GEN_FILES.items():
        for role, f in files.items():
            p = os.path.join(dest, "%s.%s.json" % (id, role))
            os.makedirs(dest, exist_ok=True)
            with open(p, "wb") as fh:
                fh.write(f())
